"""Export-only ModernBERT graph, adapted from laya-mlx; see NOTICE.

Explicit attention/head modules avoid Transformers' tracing-time backend switches.
State-dict names match original Laya checkpoints. No training or weight changes.
"""

import json
from pathlib import Path

import torch
from safetensors.torch import load_file
from torch import nn
from torch.nn import functional as F


def attention(q, k, v, mask, implementation):
    if implementation == "sdpa":
        return F.scaled_dot_product_attention(q, k, v, attn_mask=mask)
    # Alternate lowering retained for controlled conversion experiments. RangeDim
    # GPU failure also affected this implementation; enumerated shapes fix it.
    scores = torch.matmul(q, k.transpose(-2, -1)) * (q.shape[-1] ** -0.5)
    scores = torch.where(mask, scores, torch.full_like(scores, -1e4))
    return torch.matmul(F.softmax(scores, dim=-1), v)


class Embeddings(nn.Module):
    def __init__(self, cfg):
        super().__init__()
        self.tok_embeddings = nn.Embedding(cfg["vocab_size"], cfg["hidden_size"])
        self.norm = nn.LayerNorm(
            cfg["hidden_size"], eps=cfg.get("norm_eps", 1e-5), bias=cfg.get("norm_bias", False)
        )

    def forward(self, ids):
        return self.norm(self.tok_embeddings(ids))


class Attention(nn.Module):
    def __init__(self, cfg, kind, max_length):
        super().__init__()
        self.implementation = "explicit"
        d = cfg["hidden_size"]
        self.heads, self.dim = cfg["num_attention_heads"], d // cfg["num_attention_heads"]
        self.Wqkv = nn.Linear(d, 3 * d, bias=cfg.get("attention_bias", False))
        self.Wo = nn.Linear(d, d, bias=cfg.get("attention_bias", False))
        params = cfg.get("rope_parameters", {}).get(kind, {})
        if params.get("rope_type", "default") != "default":
            raise ValueError("Only default RoPE is supported")
        base = params.get(
            "rope_theta",
            cfg.get("global_rope_theta", 160000.0)
            if kind == "full_attention"
            else cfg.get("local_rope_theta", 10000.0),
        )
        inv = 1.0 / (float(base) ** (torch.arange(0, self.dim, 2).float() / self.dim))
        angles = torch.outer(torch.arange(max_length).float(), inv)
        self.register_buffer("cos", angles.cos()[None, None], persistent=False)
        self.register_buffer("sin", angles.sin()[None, None], persistent=False)

    def rotate(self, value):
        a, b = value.chunk(2, dim=-1)
        length = value.shape[-2]
        c, s = self.cos[:, :, :length], self.sin[:, :, :length]
        return torch.cat((a * c - b * s, b * c + a * s), dim=-1)

    def forward(self, x, mask):
        b, n, _ = x.shape
        qkv = self.Wqkv(x).reshape(b, n, 3, self.heads, self.dim)
        q, k, v = (qkv[:, :, i].transpose(1, 2) for i in range(3))
        value = attention(self.rotate(q), self.rotate(k), v, mask, self.implementation)
        return self.Wo(value.transpose(1, 2).reshape(b, n, -1))


class MLP(nn.Module):
    def __init__(self, cfg):
        super().__init__()
        d, h = cfg["hidden_size"], cfg["intermediate_size"]
        self.Wi = nn.Linear(d, 2 * h, bias=cfg.get("mlp_bias", False))
        self.Wo = nn.Linear(h, d, bias=cfg.get("mlp_bias", False))

    def forward(self, x):
        value, gate = self.Wi(x).chunk(2, dim=-1)
        return self.Wo(F.gelu(value) * gate)


class Layer(nn.Module):
    def __init__(self, cfg, index, kind, max_length):
        super().__init__()
        self.kind = kind

        def norm():
            return nn.LayerNorm(
                cfg["hidden_size"], eps=cfg.get("norm_eps", 1e-5), bias=cfg.get("norm_bias", False)
            )

        self.attn_norm = nn.Identity() if index == 0 else norm()
        self.attn = Attention(cfg, kind, max_length)
        self.mlp_norm = norm()
        self.mlp = MLP(cfg)

    def forward(self, x, mask):
        x = x + self.attn(self.attn_norm(x), mask)
        return x + self.mlp(self.mlp_norm(x))


class Encoder(nn.Module):
    def __init__(self, cfg, max_length):
        super().__init__()
        self.embeddings = Embeddings(cfg)
        kinds = cfg.get("layer_types") or [
            "full_attention"
            if i % cfg.get("global_attn_every_n_layers", 3) == 0
            else "sliding_attention"
            for i in range(cfg["num_hidden_layers"])
        ]
        if len(kinds) != cfg["num_hidden_layers"] or set(kinds) - {
            "full_attention",
            "sliding_attention",
        }:
            raise ValueError("Invalid layer_types")
        self.layers = nn.ModuleList(
            [Layer(cfg, i, kind, max_length) for i, kind in enumerate(kinds)]
        )
        self.final_norm = nn.LayerNorm(
            cfg["hidden_size"], eps=cfg.get("norm_eps", 1e-5), bias=cfg.get("norm_bias", False)
        )
        self.window = cfg.get("local_attention", 128)
        # Slice integer positions before building the bool mask. Slicing a
        # constant bool matrix triggers an MPSGraph compiler trap on this OS.
        self.register_buffer(
            "positions", torch.arange(max_length, dtype=torch.int32), persistent=False
        )

    def forward(self, ids, valid):
        x = self.embeddings(ids)
        full = valid[:, None, None, :]
        length = ids.shape[1]
        positions = self.positions[:length]
        window = (positions[:, None] - positions[None, :]).abs() <= self.window // 2
        local = torch.logical_and(
            torch.logical_or(window[None, None], torch.logical_not(valid[:, None, :, None])),
            full,
        )
        for layer in self.layers:
            x = layer(x, full if layer.kind == "full_attention" else local)
        return self.final_norm(x)


class HeadAttention(nn.Module):
    def __init__(self, d):
        super().__init__()
        self.implementation = "explicit"
        self.heads = max(1, d // 64)
        self.dim = d // self.heads
        self.in_proj_weight = nn.Parameter(torch.empty(3 * d, d))
        self.in_proj_bias = nn.Parameter(torch.empty(3 * d))
        self.out_proj = nn.Linear(d, d)

    def forward(self, x, mask):
        b, n, _ = x.shape
        qkv = F.linear(x, self.in_proj_weight, self.in_proj_bias).reshape(
            b, n, 3, self.heads, self.dim
        )
        q, k, v = (qkv[:, :, i].transpose(1, 2) for i in range(3))
        value = attention(q, k, v, mask, self.implementation)
        return self.out_proj(value.transpose(1, 2).reshape(b, n, -1))


class HeadLayer(nn.Module):
    def __init__(self, d):
        super().__init__()
        self.self_attn = HeadAttention(d)
        self.norm1, self.norm2 = nn.LayerNorm(d), nn.LayerNorm(d)
        self.linear1, self.linear2 = nn.Linear(d, 4 * d), nn.Linear(4 * d, d)

    def forward(self, x, mask):
        x = x + self.self_attn(self.norm1(x), mask)
        return x + self.linear2(F.relu(self.linear1(self.norm2(x))))


class Head(nn.Module):
    def __init__(self, d, layers):
        super().__init__()
        self.layers = nn.ModuleList([HeadLayer(d) for _ in range(layers)])

    def forward(self, x, mask):
        for layer in self.layers:
            x = layer(x, mask)
        return x


class DecisionModel(nn.Module):
    def __init__(self, cfg, agent_cfg, max_length):
        super().__init__()
        if cfg.get("model_type") != "modernbert" or cfg.get("hidden_activation", "gelu") != "gelu":
            raise ValueError("Only GELU ModernBERT checkpoints are supported")
        d = cfg["hidden_size"]
        self.encoder = Encoder(cfg, max_length)
        self.head = Head(d, agent_cfg["head_layers"])
        self.type_emb = nn.Embedding(3, d)
        self.scorer = nn.Sequential(nn.LayerNorm(d), nn.Linear(d, d), nn.GELU(), nn.Linear(d, 1))
        self.act_head = nn.Sequential(
            nn.Linear(d + 4, 256),
            nn.GELU(),
            nn.Linear(256, len(agent_cfg.get("act_costs", {})) + 1),
        )
        self.register_buffer("temperature", torch.ones(3))

    def forward(self, input_ids, attention_mask, marker_pos, marker_mask, qtype):
        valid, selected = attention_mask.bool(), marker_mask.bool()
        h = self.encoder(input_ids, valid) + self.type_emb(qtype)[:, None, :]
        h = self.head(h, valid[:, None, None, :])
        markers = torch.gather(h, 1, marker_pos.long()[:, :, None].expand(-1, -1, h.shape[-1]))
        logits = self.scorer(markers).squeeze(-1).float()
        logits = torch.where(selected, logits, torch.full_like(logits, -1e4))
        p = F.softmax(logits, dim=-1)
        k = selected.sum(-1).clamp(min=2).float()
        entropy = -(p * p.clamp(min=1e-9).log()).sum(-1) / k.log()
        top = p.topk(2, dim=-1).values
        features = torch.stack((top[:, 0], top[:, 0] - top[:, 1], entropy, k / 255.0), dim=-1)
        action = self.act_head(torch.cat((h[:, 0].float(), features), dim=-1))
        return logits, action.float()


def load_model(path, max_length, attention_implementation="explicit"):
    path = Path(path)
    cfg = json.loads((path / "encoder/config.json").read_text())
    agent_cfg = json.loads((path / "rl_agent_config.json").read_text())
    model = DecisionModel(cfg, agent_cfg, max_length)
    if attention_implementation not in ("explicit", "sdpa"):
        raise ValueError("attention_implementation must be explicit or sdpa")
    for module in model.modules():
        if isinstance(module, (Attention, HeadAttention)):
            module.implementation = attention_implementation
    # Original checkpoints, never rounded MLX FP16 exports.
    model.load_state_dict(load_file(str(path / "model.safetensors")), strict=True)
    return model.eval()

"""Independent BC1S/Conv transformer prototype for fixed-shape ANE export.

Uses the original checkpoint's weights and affine ordering. Layout follows the
principles in Apple's ml-ane-transformers reference, without its altered
LayerNorm affine ordering or optional clipping. Production code is untouched.
"""

import torch
from torch import nn
from torch.nn import functional as F


def conv_from_linear(linear):
    result = nn.Conv2d(linear.in_features, linear.out_features, 1, bias=linear.bias is not None)
    result.weight = nn.Parameter(linear.weight.detach()[:, :, None, None])
    if linear.bias is not None:
        result.bias = nn.Parameter(linear.bias.detach())
    return result


def conv_from_weights(weight, bias=None):
    result = nn.Conv2d(weight.shape[1], weight.shape[0], 1, bias=bias is not None)
    result.weight = nn.Parameter(weight.detach()[:, :, None, None])
    if bias is not None:
        result.bias = nn.Parameter(bias.detach())
    return result


class ChannelNorm(nn.Module):
    def __init__(self, source):
        super().__init__()
        self.eps = source.eps
        self.weight = nn.Parameter(source.weight.detach()[None, :, None, None])
        self.bias = None
        if source.bias is not None:
            self.bias = nn.Parameter(source.bias.detach()[None, :, None, None])

    def forward(self, x):
        centered = x - x.mean(dim=1, keepdim=True)
        out = centered * (centered.square().mean(dim=1, keepdim=True) + self.eps).rsqrt()
        out = out * self.weight
        return out if self.bias is None else out + self.bias


class ConvAttention(nn.Module):
    def __init__(self, source, *, rope, length):
        super().__init__()
        self.rope = rope
        self.heads, self.dim = source.heads, source.dim
        weight = source.Wqkv.weight if rope else source.in_proj_weight
        bias = source.Wqkv.bias if rope else source.in_proj_bias
        self.qkv = conv_from_weights(weight, bias)
        self.out = conv_from_linear(source.Wo if rope else source.out_proj)
        if rope:
            self.register_buffer("cos", source.cos[0, 0, :length].T[None, :, None, :])
            self.register_buffer("sin", source.sin[0, 0, :length].T[None, :, None, :])

    def rotate(self, x):
        left, right = x.chunk(2, dim=1)
        return torch.cat(
            (left * self.cos - right * self.sin, right * self.cos + left * self.sin), dim=1
        )

    def forward(self, x, mask):
        q, k, v = self.qkv(x).chunk(3, dim=1)
        output = []
        for qi, ki, vi in zip(
            q.split(self.dim, dim=1), k.split(self.dim, dim=1), v.split(self.dim, dim=1)
        ):
            if self.rope:
                qi, ki = self.rotate(qi), self.rotate(ki)
            scores = torch.einsum("bchq,bkhc->bkhq", qi, ki.transpose(1, 3)) * (self.dim**-0.5)
            probabilities = F.softmax(scores + mask, dim=1)
            output.append(torch.einsum("bkhq,bchk->bchq", probabilities, vi))
        return self.out(torch.cat(output, dim=1))


class ConvMLP(nn.Module):
    def __init__(self, source):
        super().__init__()
        self.Wi, self.Wo = conv_from_linear(source.Wi), conv_from_linear(source.Wo)

    def forward(self, x):
        value, gate = self.Wi(x).chunk(2, dim=1)
        return self.Wo(F.gelu(value) * gate)


class ConvEncoderLayer(nn.Module):
    def __init__(self, source, length):
        super().__init__()
        self.kind = source.kind
        self.attn_norm = (
            nn.Identity()
            if isinstance(source.attn_norm, nn.Identity)
            else ChannelNorm(source.attn_norm)
        )
        self.attn = ConvAttention(source.attn, rope=True, length=length)
        self.mlp_norm = ChannelNorm(source.mlp_norm)
        self.mlp = ConvMLP(source.mlp)

    def forward(self, x, mask):
        x = x + self.attn(self.attn_norm(x), mask)
        return x + self.mlp(self.mlp_norm(x))


class ConvHeadLayer(nn.Module):
    def __init__(self, source, length):
        super().__init__()
        self.norm1, self.norm2 = ChannelNorm(source.norm1), ChannelNorm(source.norm2)
        self.attn = ConvAttention(source.self_attn, rope=False, length=length)
        self.linear1, self.linear2 = (
            conv_from_linear(source.linear1),
            conv_from_linear(source.linear2),
        )

    def forward(self, x, mask):
        x = x + self.attn(self.norm1(x), mask)
        return x + self.linear2(F.relu(self.linear1(self.norm2(x))))


class ConvBody(nn.Module):
    """Embedding norm, full encoder, type addition, full decision head and scorer.

    Inputs: raw embedding lookup BC1S, additive attention masks BK1Q, type vector
    BC11, and one-hot marker selectors BL1K. Outputs: option logits and CLS hidden.
    Small action-head features and calibrated output formatting remain on the CPU.
    """

    def __init__(self, source, length):
        super().__init__()
        self.embedding_norm = ChannelNorm(source.encoder.embeddings.norm)
        self.layers = nn.ModuleList(
            [ConvEncoderLayer(layer, length) for layer in source.encoder.layers]
        )
        self.final_norm = ChannelNorm(source.encoder.final_norm)
        self.head = nn.ModuleList([ConvHeadLayer(layer, length) for layer in source.head.layers])
        self.scorer = nn.Sequential(
            ChannelNorm(source.scorer[0]),
            conv_from_linear(source.scorer[1]),
            nn.GELU(),
            conv_from_linear(source.scorer[3]),
        )

    def forward(self, embeddings, full_mask, local_mask, type_vectors, marker_map):
        x = self.embedding_norm(embeddings)
        for layer in self.layers:
            x = layer(x, full_mask if layer.kind == "full_attention" else local_mask)
        x = self.final_norm(x) + type_vectors
        for layer in self.head:
            x = layer(x, full_mask)
        markers = torch.einsum("bkhq,bchk->bchq", marker_map, x)
        return self.scorer(markers), x[:, :, :, :1]

import numpy as np
import pytest

from laya_coreml.inputs import collate_items
from laya_coreml.prompt import PromptMixin


def shape(**kwargs):
    return {
        "batch_size": 3,
        "max_length": 128,
        "min_length": 16,
        "max_options": 4,
        "flexible": True,
        **kwargs,
    }


def item(length=17, markers=None):
    return {"ids": list(range(length)), "markers": markers or [3, 6], "qtype": 2}


def test_partial_batch_and_padding():
    arrays = collate_items([item()], 9, shape=shape())
    assert arrays["input_ids"].shape == (3, 32)
    assert all(v.dtype == np.int32 for v in arrays.values())
    assert arrays["attention_mask"].sum(axis=1).tolist() == [17, 1, 1]
    assert arrays["marker_mask"].sum(axis=1).tolist() == [2, 0, 0]
    assert arrays["input_ids"][0, 17:].tolist() == [9] * 15
    assert arrays["qtype"].tolist() == [2, 0, 0]


@pytest.mark.parametrize("length,expected", [(4, 16), (16, 16), (17, 32), (64, 64), (127, 128)])
def test_flexible_length_buckets(length, expected):
    batch = collate_items([item(length)], 0, shape=shape())
    assert batch["input_ids"].shape[1] == expected


def test_fixed_length_does_not_silently_truncate():
    batch = collate_items([item(17)], 0, shape=shape(flexible=False))
    assert batch["input_ids"].shape[1] == 128
    with pytest.raises(ValueError, match="129 tokens"):
        collate_items([item(129)], 0, shape=shape(flexible=False))


@pytest.mark.parametrize("items", [[], [item()] * 4, [item(markers=[1, 2, 3, 4, 5])]])
def test_reject_export_capacity_overflow(items):
    with pytest.raises(ValueError):
        collate_items(items, 0, shape=shape())


@pytest.mark.parametrize(
    "definition",
    [
        {"type": "freeform", "instructions": "hi"},
        {"type": "choice", "criteria": ["a"]},
        {"type": "choice", "instructions": "hi", "criteria": []},
        {"type": "choice", "instructions": "hi", "criteria": ["a", "a"]},
        {"type": "score", "instructions": "hi", "criteria": {}},
    ],
)
def test_reject_invalid_question(definition):
    with pytest.raises(ValueError):
        PromptMixin._to_internal(definition)


def test_structured_question_criteria_preserved():
    result = PromptMixin._to_internal(
        {
            "type": "choice",
            "instructions": {"task": "pick"},
            "criteria": {"zero": 0, "false": False, "object": {"x": 1}},
        }
    )
    assert result["crit"] == {"zero": 0, "false": False, "object": {"x": 1}}


def test_known_failed_gpu_configuration_is_rejected_before_loading(tmp_path):
    import json

    from laya_coreml import Agent

    (tmp_path / "coreml_config.json").write_text(
        json.dumps(
            {
                "format": "laya-coreml",
                "format_version": 1,
                "shape": shape(),
            }
        )
    )
    with pytest.raises(ValueError, match="failed local fidelity"):
        Agent(tmp_path, compute_units="cpu_gpu")


def test_enumerated_shapes_select_next_bucket():
    batch = collate_items([item(65)], 0, shape=shape(lengths=[16, 32, 64, 96, 128]))
    assert batch["input_ids"].shape[1] == 96
